 77→	}
 78→	var resp DetectResponse
 79→	if err := json.Unmarshal(stdout, &resp); err != nil {
 80→		return false, fmt.Errorf("detect: invalid JSON: %w", err)
 81→	}
 82→	return resp.Present, nil
 83→}
