 95→func (e *Agent) ChunkTranscript(ctx context.Context, content []byte, maxSize int) ([][]byte, error) {
 96→	stdout, err := e.run(ctx, content, "chunk-transcript", "--max-size", strconv.Itoa(maxSize))
