204→func (e *Agent) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
205→	data, err := io.ReadAll(stdin)
206→	if err != nil {
207→		return nil, fmt.Errorf("parse-hook: read stdin: %w", err)
208→	}
209→	stdout, err := e.run(ctx, data, "parse-hook", "--hook", hookName)
210→	if err != nil {
