212→	}
213→	// null means no lifecycle significance
214→	if bytes.Equal(bytes.TrimSpace(stdout), []byte("null")) {
215→		return nil, nil //nolint:nilnil // protocol contract: null = no event
216→	}
217→	var event eventJSON
218→	if err := json.Unmarshal(stdout, &event); err != nil {
219→		return nil, fmt.Errorf("parse-hook: invalid JSON: %w", err)
220→	}
221→	return event.toEvent()
