426→// --- Helpers ---
427→
428→func marshalHookInput(input *agent.HookInput) ([]byte, error) {
429→	if input == nil {
430→		return []byte("{}"), nil
431→	}
432→	j := HookInputJSON{
433→		HookType:   string(input.HookType),
434→		SessionID:  input.SessionID,
435→		SessionRef: input.SessionRef,
436→		Timestamp:  input.Timestamp.Format(time.RFC3339),
437→		UserPrompt: input.UserPrompt,
438→		ToolName:   input.ToolName,
439→		ToolUseID:  input.ToolUseID,
440→		ToolInput:  input.ToolInput,
441→		RawData:    input.RawData,
442→	}
443→	data, err := json.Marshal(j)
444→	if err != nil {
445→		return nil, fmt.Errorf("marshal hook input: %w", err)
446→	}
447→	return data, nil
448→}
449→
450→func marshalAgentSession(s *agent.AgentSession) ([]byte, error) {
451→	j := AgentSessionJSON{
452→		SessionID:     s.SessionID,
453→		AgentName:     string(s.AgentName),
454→		RepoPath:      s.RepoPath,
455→		SessionRef:    s.SessionRef,
456→		StartTime:     s.StartTime.Format(time.RFC3339),
457→		NativeData:    s.NativeData,
458→		ModifiedFiles: s.ModifiedFiles,
459→		NewFiles:      s.NewFiles,
460→		DeletedFiles:  s.DeletedFiles,
461→	}
462→	data, err := json.Marshal(j)
463→	if err != nil {
464→		return nil, fmt.Errorf("marshal agent session: %w", err)
465→	}
466→	return data, nil
467→}
468→
469→func unmarshalAgentSession(j *AgentSessionJSON) (*agent.AgentSession, error) {
470→	var startTime time.Time
471→	if j.StartTime != "" {
472→		var err error
473→		startTime, err = time.Parse(time.RFC3339, j.StartTime)
474→		if err != nil {
475→			return nil, fmt.Errorf("invalid start_time: %w", err)
476→		}
477→	}
478→	return &agent.AgentSession{
479→		SessionID:     j.SessionID,
480→		AgentName:     types.AgentName(j.AgentName),
481→		RepoPath:      j.RepoPath,
482→		SessionRef:    j.SessionRef,
483→		StartTime:     startTime,
484→		NativeData:    j.NativeData,
485→		ModifiedFiles: j.ModifiedFiles,
486→		NewFiles:      j.NewFiles,
487→		DeletedFiles:  j.DeletedFiles,
488→	}, nil
489→}
490→
491→func convertTokenUsage(r *TokenUsageResponse) *agent.TokenUsage {
492→	if r == nil {
493→		return nil
494→	}
495→	usage := &agent.TokenUsage{
496→		InputTokens:         r.InputTokens,
497→		CacheCreationTokens: r.CacheCreationTokens,
498→		CacheReadTokens:     r.CacheReadTokens,
499→		OutputTokens:        r.OutputTokens,
500→		APICallCount:        r.APICallCount,
501→	}
502→	if r.SubagentTokens != nil {
503→		usage.SubagentTokens = convertTokenUsage(r.SubagentTokens)
504→	}
505→	return usage
506→}
