 11→// Wrap returns the Agent wrapped with the appropriate interface
 12→// implementations based on the capabilities declared in its info response.
 13→// The returned value satisfies agent.Agent and whichever optional interfaces
 14→// the external binary declared support for.
 15→//
 16→// We cannot use Go embedding because *Agent implements ALL optional interface
 17→// methods, and embedding would expose all of them regardless of capabilities.
 18→// Instead, each wrapper explicitly forwards only the interfaces it should expose.
 19→func Wrap(ea *Agent) agent.Agent {
 20→	caps := ea.info.Capabilities
 21→
 22→	base := baseAgent{ea: ea}
 23→
 24→	switch {
 25→	case caps.Hooks && caps.TranscriptAnalyzer && caps.TokenCalculator && caps.TextGenerator && caps.HookResponseWriter && caps.SubagentAwareExtractor:
 26→		return &fullAgent{baseAgent: base}
 27→	case caps.Hooks && caps.TranscriptAnalyzer:
 28→		return &hooksAnalyzerAgent{baseAgent: base}
 29→	case caps.Hooks:
 30→		return &hooksAgent{baseAgent: base}
 31→	case caps.TranscriptAnalyzer:
 32→		return &analyzerAgent{baseAgent: base}
 33→	default:
 34→		return &base
 35→	}
 36→}
